1	import type { Socket } from "socket.io";
2	import { Participant } from "../../models/participantModel.js";
3	import { Room } from "../../models/roomModel.js";
4	
5	/**
6	 * Middleware to authenticate and authorize a Socket.IO connection.
7	 * Validates that the session token exists and matches the specified room.
8	 */
9	export async function socketAuthMiddleware(
10	  socket: Socket,
11	  next: (err?: Error) => void
12	): Promise<void> {
13	  try {
14	    const sessionToken = socket.handshake.auth.sessionToken;
15	    const roomCode = socket.handshake.auth.roomCode;
16	
17	    if (!sessionToken || !roomCode) {
18	      return next(new Error("Authentication failed: Missing credentials."));
19	    }
20	
21	    // 1. Find participant by sessionToken
