1	import { useEffect, useState } from "react";
2	import { connectSocket, disconnectSocket } from "../services/socket";
3	import { useSessionStore } from "../stores/useSessionStore";
4	import type { AuctionItem, Bid, Participant, Room } from "../services/api";
5	
6	export type ConnectionStatus = "connecting" | "connected" | "disconnected";
7	
8	function mergeItems(current: AuctionItem[], incoming: AuctionItem[]): AuctionItem[] {
9	  const byId = new Map(current.map((item) => [item._id, item]));
10	  for (const item of incoming) byId.set(item._id, item);
11	  return [...byId.values()].sort((a, b) => a.createdAt.localeCompare(b.createdAt));
12	}
13	
14	/** Manages one room-scoped socket and applies server-authoritative state updates. */
15	export function useSocket(roomCode: string) {
16	  const sessionToken = useSessionStore((state) => state.sessionToken);
17	  const hasSession = Boolean(roomCode && sessionToken);
18	  const [status, setStatus] = useState<ConnectionStatus>("connecting");
19	  const [room, setRoom] = useState<Room | null>(null);
20	  const [participants, setParticipants] = useState<Participant[]>([]);
21	  const [items, setItems] = useState<AuctionItem[]>([]);
22	  const [activeItem, setActiveItem] = useState<AuctionItem | null>(null);
23	  const [activeItemStartedAt, setActiveItemStartedAt] = useState<string | null>(null);
24	  const [bids, setBids] = useState<Bid[]>([]);
25	  const [bidError, setBidError] = useState<{ reason: string; minimumBid: number } | null>(null);
26	  const [error, setError] = useState<string | null>(null);
27	
28	  useEffect(() => {
29	    if (!roomCode || !sessionToken) return;
30	
31	    const socket = connectSocket(roomCode, sessionToken);
32	
33	    const handleConnect = () => {
34	      setStatus("connected");
35	      setError(null);
36	      socket.emit("room:connect");
37	    };
38	    const handleDisconnect = () => setStatus("disconnected");
39	    const handleConnectError = (connectionError: Error) => {
40	      setStatus("disconnected");
41	      setError(connectionError.message || "Failed to connect to the realtime server.");
42	    };
43	    const handleRoomState = (data: {
44	      room: Room;
45	      participants: Participant[];
46	      activeItem: AuctionItem | null;
47	      bids: Bid[];
48	      items: AuctionItem[];
49	    }) => {
50	      setRoom(data.room);
51	      setParticipants(data.participants);
52	      setActiveItem(data.activeItem);
53	      setBids(data.bids);
54	      // Merge rather than replace: a concurrent item:added event can never be lost.
55	      setItems((current) => mergeItems(current, data.items));
56	    };
57	    const handleParticipantJoined = (data: { participant: Participant }) => {
58	      setParticipants((current) => {
59	        const exists = current.some((participant) => participant._id === data.participant._id);
60	        return exists
61	          ? current.map((participant) => participant._id === data.participant._id
62	            ? { ...participant, isConnected: true }
63	            : participant)
64	          : [...current, data.participant];
65	      });
66	    };
67	    const handleParticipantLeft = (data: { participant: Participant }) => {
68	      setParticipants((current) => current.map((participant) => participant._id === data.participant._id
69	        ? { ...participant, isConnected: false }
70	        : participant));
71	    };
72	    const handleItemAdded = (data: { item: AuctionItem }) => {
73	      setItems((current) => mergeItems(current, [data.item]));
74	    };
75	    const handleAuctionStarted = (data: { room: Room }) => setRoom(data.room);
76	    const handleItemActivated = (data: { item: AuctionItem; startedAt: string; endsAt: string }) => {
77	      setActiveItem(data.item);
78	      setActiveItemStartedAt(data.startedAt);
79	      setBids([]);
80	      setBidError(null);
81	      setRoom((current) => current ? { ...current, status: "live", endsAt: data.endsAt } : current);
82	    };
83	    const handleBidAccepted = (data: { bid: Bid; item: AuctionItem }) => {
84	      setActiveItem(data.item);
85	      setBids((current) => current.some((bid) => bid._id === data.bid._id) ? current : [data.bid, ...current]);
86	      setBidError(null);
87	      if (data.item.endsAt) {
88	        setRoom((current) => current ? { ...current, endsAt: data.item.endsAt } : current);
89	      }
90	    };
91	    const handleBidRejected = (data: { reason: string; minimumBid: number }) => setBidError(data);
92	    const handleItemEnded = () => {
93	      setActiveItem(null);
94	      setBids([]);
95	      setBidError(null);
96	    };
97	    const handleAuctionCompleted = (data: { room: Room }) => {
98	      setRoom(data.room);
99	      setActiveItem(null);
100	      setBids([]);
101	    };
102	
103	    socket.on("connect", handleConnect);
104	    socket.on("disconnect", handleDisconnect);
105	    socket.on("connect_error", handleConnectError);
106	    socket.on("room:state", handleRoomState);
107	    socket.on("participant:joined", handleParticipantJoined);
108	    socket.on("participant:left", handleParticipantLeft);
109	    socket.on("item:added", handleItemAdded);
110	    socket.on("auction:started", handleAuctionStarted);
111	    socket.on("item:activated", handleItemActivated);
112	    socket.on("bid:accepted", handleBidAccepted);
113	    socket.on("bid:rejected", handleBidRejected);
114	    socket.on("item:ended", handleItemEnded);
115	    socket.on("auction:completed", handleAuctionCompleted);
116	
117	    if (socket.connected) handleConnect();
118	
119	    return () => {
120	      socket.off("connect", handleConnect);
121	      socket.off("disconnect", handleDisconnect);
122	      socket.off("connect_error", handleConnectError);
123	      socket.off("room:state", handleRoomState);
124	      socket.off("participant:joined", handleParticipantJoined);
125	      socket.off("participant:left", handleParticipantLeft);
126	      socket.off("item:added", handleItemAdded);
127	      socket.off("auction:started", handleAuctionStarted);
128	      socket.off("item:activated", handleItemActivated);
129	      socket.off("bid:accepted", handleBidAccepted);
130	      socket.off("bid:rejected", handleBidRejected);
131	      socket.off("item:ended", handleItemEnded);
132	      socket.off("auction:completed", handleAuctionCompleted);
133	      disconnectSocket();
134	    };
135	  }, [roomCode, sessionToken]);
136	
137	  return {
138	    status: hasSession ? status : "disconnected",
139	    room,
140	    participants,
141	    items,
142	    activeItem,
143	    activeItemStartedAt,
144	    bids,
145	    bidError,
